import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/moran_local_2023_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
df['NO2_value'] = df['NO2_value'].fillna(df['NO2_value'].mean())

# Calculate neighborhood NO2 values
neighborhood_values = {}
for index, row in adjacency.iterrows():
    borough = row['borough']
    neighbors = adjacency.loc[adjacency['neighbor'] == borough, 'borough'].tolist()
    neighborhood_values[borough] = df.loc[df['borough'].isin(neighbors), 'NO2_value'].mean()

# Classify boroughs as HOT SPOT or COLD SPOT
classifications = {}
for index, row in df.iterrows():
    borough = row['borough']
    neighbor_avg = neighborhood_values[borough]
    if row['NO2_value'] > neighbor_avg:
        classifications[borough] = 'HOT SPOT'
    elif row['NO2_value'] < neighbor_avg:
        classifications[borough] = 'COLD SPOT'
    else:
        classifications[borough] = 'NEUTRAL'

# Compute statistical significance
significance = {}
for borough, classification in classifications.items():
    if classification != 'NEUTRAL':
        values = df.loc[df['borough'] == borough, 'NO2_value'].values
        neighbor_values = df.loc[df['borough'].isin(adjacency.loc[adjacency['neighbor'] == borough, 'borough'].tolist()), 'NO2_value'].values
        test_statistic = np.mean(values) - np.mean(neighbor_values)
        p_value = np.mean(np.sign(np.random.choice(values, size=len(values)) - np.random.choice(neighbor_values, size=len(neighbor_values))) > 0 for _ in range(500))
        significance[borough] = (test_statistic, p_value)

# Identify final HOT SPOTS and COLD SPOTS
final_classifications = {}
for borough, (test_statistic, p_value) in significance.items():
    if p_value < 0.05:
        final_classifications[borough] = (classification, test_statistic)

# List final results
data_points_used = len(df)
final_answer = ', '.join(f'{borough} ({classification}, statistical method={test_statistic})' for borough, (classification, test_statistic) in final_classifications.items())
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {final_answer}')

import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2023_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['NO2_value'] = data['NO2_value'].fillna(data['NO2_value'].mean())

# Calculate neighborhood NO2 values
neighborhood_values = {}
for index, row in adjacency.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhood_values:
        neighborhood_values[borough] = []
    if neighbor not in neighborhood_values:
        neighborhood_values[neighbor] = []
    neighborhood_values[borough].append(data.loc[data['borough'] == neighbor, 'NO2_value'].values[0])
    neighborhood_values[neighbor].append(data.loc[data['borough'] == borough, 'NO2_value'].values[0])

# Calculate average neighborhood NO2 values
for borough in neighborhood_values:
    neighborhood_values[borough] = np.mean(neighborhood_values[borough])

# Classify boroughs as HOT SPOT or COLD SPOT
hot_spots = []
cold_spots = []
for index, row in data.iterrows():
    borough = row['borough']
    if data.loc[data['borough'] == borough, 'NO2_value'].values[0] > neighborhood_values[borough]:
        hot_spots.append(borough)
    elif data.loc[data['borough'] == borough, 'NO2_value'].values[0] < neighborhood_values[borough]:
        cold_spots.append(borough)

# Compute statistical significance
def permutation_test(boroughs, classification):
    test_statistic = 0
    significance_measure = 0
    for borough in boroughs:
        neighbor_values = neighborhood_values[borough]
        neighbor_values = np.delete(neighbor_values, np.where(neighbor_values == data.loc[data['borough'] == borough, 'NO2_value'].values[0]))
        if classification == 'HOT SPOT':
            test_statistic += data.loc[data['borough'] == borough, 'NO2_value'].values[0] - np.mean(neighbor_values)
        else:
            test_statistic += np.mean(neighbor_values) - data.loc[data['borough'] == borough, 'NO2_value'].values[0]
    test_statistic /= len(boroughs)
    p_value = 0
    for _ in range(500):
        permutation = np.random.permutation(data['NO2_value'])
        permutation = permutation[data['borough'].isin(boroughs)]
        permutation_test_statistic = 0
        for borough in boroughs:
            neighbor_values = neighborhood_values[borough]
            neighbor_values = np.delete(neighbor_values, np.where(neighbor_values == data.loc[data['borough'] == borough, 'NO2_value'].values[0]))
            if classification == 'HOT SPOT':
                permutation_test_statistic += permutation[np.where(data['borough'] == borough)[0][0]] - np.mean(neighbor_values)
            else:
                permutation_test_statistic += np.mean(neighbor_values) - permutation[np.where(data['borough'] == borough)[0][0]]
        permutation_test_statistic /= len(boroughs)
        if permutation_test_statistic >= test_statistic:
            p_value += 1
    significance_measure = 1 - (p_value / 500)
    return test_statistic, significance_measure

hot_spots_test_statistic, hot_spots_significance_measure = permutation_test(hot_spots, 'HOT SPOT')
cold_spots_test_statistic, cold_spots_significance_measure = permutation_test(cold_spots, 'COLD SPOT')

# Identify final HOT SPOTS and COLD SPOTS
final_hot_spots = []
final_cold_spots = []
for borough in hot_spots:
    if hot_spots_significance_measure > 0.05:
        final_hot_spots.append(borough)
for borough in cold_spots:
    if cold_spots_significance_measure > 0.05:
        final_cold_spots.append(borough)

# List final results
data_points_used = len(data)
print(f'data_points_used = {data_points_used}')
if final_hot_spots:
    print(f'FINAL ANSWER: {", ".join(final_hot_spots)} (HH, statistical method={hot_spots_test_statistic}, significance measure={hot_spots_significance_measure})')
else:
    print(f'FINAL ANSWER: none')
if final_cold_spots:
    print(f'FINAL ANSWER: {", ".join(final_cold_spots)} (LL, statistical method={cold_spots_test_statistic}, significance measure={cold_spots_significance_measure})')
else:
    print(f'FINAL ANSWER: none')
